'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const { createRequire } = require('node:module');
const [repo, mode = 'dev', packaged] = process.argv.slice(2);
const load = createRequire(path.join(repo, 'package.json'));
const { _electron } = load('playwright');
const { sanitizeTestEnv } = load('./test/test-env');
const output = fs.mkdtempSync(path.join(os.tmpdir(), `pd-r7-${mode}-`));
console.log(`Proof artifacts: ${output}`);
const home = path.join(output, 'home');
fs.mkdirSync(home);
fs.mkdirSync(path.join(output, 'tmux'));
const inherited = Object.fromEntries(['PATH', 'DISPLAY', 'XAUTHORITY', 'LANG'].filter(key => process.env[key]).map(key => [key, process.env[key]]));
const env = { ...sanitizeTestEnv({ ...inherited, HOME: home }), TMUX_TMPDIR: path.join(output, 'tmux'),
  XDG_CONFIG_HOME: path.join(home, '.config'), XDG_CACHE_HOME: path.join(home, '.cache'),
  PI_DISH_URL: 'https://foreign.invalid/not-our-listener', R7_DELAY_MS: '1500', R7_TRACE: path.join(output, 'trace.json') };
(async () => {
  const app = await require('/tmp/pi-dish-parent-r7-main-YyExzk/pi-dish-r7-electron-launch.cjs')(_electron, { executablePath: mode === 'dev' ? load('electron') : packaged,
    args: ['-r', '/tmp/pi-dish-parent-r7-main-YyExzk/pi-dish-r7-electron-preload.cjs', ...(mode === 'dev' ? [path.join(repo, 'electron/main.js')] : [])],
    cwd: output, env, timeout: 30000 }, mode === 'packaged');
  const logs = [];
  app.process().stdout?.on('data', data => logs.push(String(data)));
  app.process().stderr?.on('data', data => logs.push(String(data)));
  try {
    const window = await app.firstWindow({ timeout: 20000 });
    await window.waitForLoadState('domcontentloaded');
    const trace = await app.evaluate(() => globalThis.__r7Proof);
    fs.writeFileSync(path.join(output, 'observed.json'), JSON.stringify(trace, null, 2));
    assert.equal(trace.loads.length, 1);
    const first = trace.loads[0];
    const ready = trace.binds.find(bind => bind.listening && bind.listening <= first.at);
    assert.ok(ready, `navigation preceded owned listener readiness: ${JSON.stringify(trace)}`);
    assert.ok(ready.listening - ready.called >= 1400, 'real bind must be delayed beyond old300ms');
    assert.equal(new URL(first.url).port, String(ready.address.port));
    assert.equal(new URL(first.url).hostname, '127.0.0.1');
    const response = await fetch(`${first.url}/api/host`);
    assert.equal(response.status, 200);
    const host = await response.json();
    assert.ok(host.hostId);
    await window.locator('.global-settings-btn').waitFor({ state: 'visible' });
    assert.equal(await window.evaluate(() => typeof window.require), 'undefined');
    const root = await app.evaluate(({ app }, repo) => {
      const path = process.getBuiltinModule('node:path');
      const load = process.getBuiltinModule('node:module').createRequire(path.join(app.isPackaged ? app.getAppPath() : repo, 'package.json'));
      const server = load('./server.js');
      return { packaged: app.isPackaged, applicationPath: app.getAppPath(), native: server instanceof process.getBuiltinModule('node:http').Server, listening: server.listening, address: server.address(), versions: process.versions };
    }, repo);
    assert.equal(root.native, true);
    assert.equal(root.packaged, mode === 'packaged');
    assert.equal(root.listening, true);
    assert.equal(root.address.port, ready.address.port);
    await window.screenshot({ path: path.join(output, 'window.png'), fullPage: false });
    fs.writeFileSync(path.join(output, 'result.json'), JSON.stringify({ mode, result: 'PASS', host, root, trace }, null, 2));
    console.log(`${mode}: actual delayed-bind/PORT0/foreign-advertised-URL/root-identity proof PASS`);
  } finally {
    await app.close();
    fs.writeFileSync(path.join(output, 'process.log'), logs.join(''));
  }
})().catch(error => { console.error(error); process.exitCode = 1; });

'use strict';
const assert = require('node:assert/strict');
const childProcess = require('node:child_process');
const fs = require('node:fs');

async function injectBeforeMain(url, traceFile, preloadPath) {
  const socket = new WebSocket(url);
  let nextId = 0;
  const pending = new Map();
  let paused;
  const onPause = new Promise(resolve => { paused = resolve; });
  socket.addEventListener('message', event => {
    const message = JSON.parse(String(event.data));
    if (message.id) {
      const request = pending.get(message.id);
      if (!request) return;
      pending.delete(message.id);
      if (message.error) request.reject(new Error(JSON.stringify(message.error)));
      else request.resolve(message.result);
    } else if (message.method === 'Debugger.paused') paused(message.params);
  });
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const id = ++nextId;
    pending.set(id, { resolve, reject });
    socket.send(JSON.stringify({ id, method, params }));
  });
  try {
    await new Promise((resolve, reject) => { socket.addEventListener('open', resolve, { once: true }); socket.addEventListener('error', reject, { once: true }); });
    await send('Debugger.enable');
    await send('Runtime.runIfWaitingForDebugger');
    const pause = await onPause;
    const entry = await send('Debugger.evaluateOnCallFrame', {
      callFrameId: pause.callFrames[0].callFrameId,
      expression: "({ filename: __filename, packaged: require('electron').app.isPackaged })",
      returnByValue: true,
    });
    if (entry.exceptionDetails) throw new Error(JSON.stringify(entry.exceptionDetails));
    assert.equal(entry.result.value.packaged, true);
    assert.ok(entry.result.value.filename.endsWith('/app.asar/electron/main.js'));
    fs.writeFileSync(`${traceFile}.injection.json`, JSON.stringify({ reason: pause.reason, entry: entry.result.value, frames: pause.callFrames.map(frame => ({ url: frame.url, functionName: frame.functionName, location: frame.location })) }, null, 2));
    const result = await send('Debugger.evaluateOnCallFrame', {
      callFrameId: pause.callFrames[0].callFrameId,
      expression: `require(${JSON.stringify(preloadPath)}); 'r7-native-preload-injected'`,
      returnByValue: true,
    });
    if (result.exceptionDetails) throw new Error(JSON.stringify(result.exceptionDetails));
    assert.equal(result.result.value, 'r7-native-preload-injected');
    await send('Debugger.resume');
  } finally { socket.close(); }
}

module.exports = async function launchElectron(electron, options, packaged) {
  if (!packaged) return electron.launch(options);
  // Packaged Electron ignores -r. Inject the exact same throwaway observer into
  // its paused native entry frame, without replacing its entry or changing ASAR.
  const nativeSpawn = childProcess.spawn;
  let child;
  let injectedResolve;
  let injectedReject;
  const injected = new Promise((resolve, reject) => { injectedResolve = resolve; injectedReject = reject; });
  childProcess.spawn = function (...args) {
    const result = nativeSpawn.apply(this, args);
    if (args[0] === options.executablePath) {
      child = result;
      let captured = false;
      let stderr = '';
      result.stderr.on('data', bytes => {
        stderr += String(bytes);
        const match = stderr.match(/Debugger listening on (ws:\/\/[^\s]+)/);
        if (!captured && match) {
          captured = true;
          injectBeforeMain(match[1], options.env.R7_TRACE, options.args[1]).then(injectedResolve, injectedReject);
        }
      });
    }
    return result;
  };
  try {
    assert.equal(options.args[0], '-r');
    const launched = electron.launch({ ...options, args: ['--inspect-brk=0', ...options.args.slice(2)] });
    const app = await Promise.race([launched, injected.then(() => launched)]);
    await injected;
    return app;
  } catch (error) {
    if (child?.exitCode === null) child.kill('SIGTERM');
    throw error;
  } finally { childProcess.spawn = nativeSpawn; }
};

'use strict';
const net = require('node:net');
const http = require('node:http');
const fs = require('node:fs');
const { errorMonitor } = require('node:events');
const electron = require('electron');
const nativeListen = net.Server.prototype.listen;
const originalLoad = electron.BrowserWindow.prototype.loadURL;
const originalDialog = electron.dialog.showErrorBox;
const trace = globalThis.__r7Proof = { started: Date.now(), binds: [], loads: [], dialogs: [] };
function save() { fs.writeFileSync(process.env.R7_TRACE, JSON.stringify(trace, null, 2)); }
net.Server.prototype.listen = function (...args) {
  if (!(this instanceof http.Server)) return nativeListen.apply(this, args);
  const item = { called: Date.now(), port: args[0], host: args[1] };
  trace.binds.push(item);
  this.prependOnceListener('listening', () => { item.listening = Date.now(); item.address = this.address(); save(); });
  this.prependOnceListener(errorMonitor, error => { item.error = error.message; save(); });
  save();
  const mainDelay = typeof args[0] === 'number' ? process.env.R7_MAIN_DELAY_MS : undefined;
  setTimeout(() => nativeListen.apply(this, args), Number(mainDelay || process.env.R7_DELAY_MS || 1500));
  return this;
};
electron.BrowserWindow.prototype.loadURL = function (url, ...args) {
  trace.loads.push({ at: Date.now(), url });
  save();
  return originalLoad.call(this, url, ...args);
};
electron.dialog.showErrorBox = function (title, content) {
  trace.dialogs.push({ at: Date.now(), title, content });
  save();
  return originalDialog.call(this, title, content);
};
save();

'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const net = require('node:net');
const { createRequire } = require('node:module');
const { execFile } = require('node:child_process');
const { promisify } = require('node:util');
const { setTimeout: delay } = require('node:timers/promises');
const run = promisify(execFile);
const [repo, mode = 'dev', packaged] = process.argv.slice(2);
const load = createRequire(path.join(repo, 'package.json'));
const { _electron } = load('playwright');
const { sanitizeTestEnv } = load('./test/test-env');
const output = fs.mkdtempSync(path.join(os.tmpdir(), `pd-r7-failure-${mode}-`));
console.log(`Failure artifacts: ${output}`);
const home = path.join(output, 'home');
fs.mkdirSync(home);
fs.mkdirSync(path.join(output, 'tmux'));
const inherited = Object.fromEntries(['PATH', 'DISPLAY', 'XAUTHORITY', 'LANG'].filter(key => process.env[key]).map(key => [key, process.env[key]]));
const env = { ...sanitizeTestEnv({ ...inherited, HOME: home }), TMUX_TMPDIR: path.join(output, 'tmux'),
  XDG_CONFIG_HOME: path.join(home, '.config'), XDG_CACHE_HOME: path.join(home, '.cache'),
  R7_DELAY_MS: '1500', R7_TRACE: path.join(output, 'trace.json') };
const watchdog = setTimeout(() => { console.error('Main failure proof watchdog expired'); process.exit(1); }, 35000);
(async () => {
  const sockets = new Set();
  const occupied = net.createServer(socket => {
    sockets.add(socket);
    socket.on('close', () => sockets.delete(socket));
    socket.end();
  });
  await new Promise(resolve => occupied.listen(0, '127.0.0.1', resolve));
  env.PORT = String(occupied.address().port);
  let app;
  let child;
  try {
    app = await require('/tmp/pi-dish-parent-r7-main-YyExzk/pi-dish-r7-electron-launch.cjs')(_electron, { executablePath: mode === 'dev' ? load('electron') : packaged,
      args: ['-r', '/tmp/pi-dish-parent-r7-main-YyExzk/pi-dish-r7-electron-preload.cjs', ...(mode === 'dev' ? [path.join(repo, 'electron/main.js')] : [])],
      cwd: output, env, timeout: 30000 }, mode === 'packaged');
    child = app.process();
    const exit = new Promise(resolve => child.once('exit', (code, signal) => resolve({ code, signal })));
    let trace;
    for (let i = 0; i < 200; i++) {
      trace = JSON.parse(fs.readFileSync(env.R7_TRACE));
      if (trace.dialogs.length) break;
      if (child.exitCode !== null) throw new Error(`Exited before visible startup failure: ${child.exitCode}`);
      await delay(50);
    }
    assert.equal(trace.dialogs.length, 1, 'actual native error dialog is required');
    assert.match(trace.dialogs[0].content, /EADDRINUSE|address already in use/i);
    assert.deepEqual(trace.loads, [], 'startup failure must not open an empty browser window');
    await delay(400);
    await run('import', ['-window', 'root', path.join(output, 'dialog.png')], { env });
    await run('python3', ['/tmp/pi-dish-parent-r7-main-YyExzk/pi-dish-r7-dismiss-dialog.py'], { env });
    const ended = await Promise.race([exit, delay(10000).then(() => { throw new Error('Electron did not exit after dismissing failure'); })]);
    assert.deepEqual(ended, { code: 1, signal: null });
    assert.equal(occupied.listening, true);
    fs.writeFileSync(path.join(output, 'result.json'), JSON.stringify({ result: 'PASS', mode, ended, trace }, null, 2));
    console.log(`${mode}: native startup failure dialog, zero navigation, exit1 PASS`);
  } catch (error) {
    console.error(error);
    process.exitCode = 1;
  } finally {
    try { if (app && child?.exitCode === null) await app.close(); }
    finally {
      for (const socket of sockets) socket.destroy();
      await new Promise(resolve => occupied.close(resolve));
      clearTimeout(watchdog);
    }
  }
})().catch(error => { console.error(error); process.exitCode = 1; clearTimeout(watchdog); });

'use strict';
const fs = require('node:fs');
const net = require('node:net');
const electron = require('electron');
const trace = { loads: [], dialogs: [], throws: [], monitor: [] };
const save = () => fs.writeFileSync(process.env.R7_TRACE, JSON.stringify(trace, null, 2));
const listen = net.Server.prototype.listen;
net.Server.prototype.listen = function (...args) {
  try { return listen.apply(this, args); }
  catch (error) {
    trace.throws.push({ at: Date.now(), name: error.name, code: error.code, message: error.message });
    save();
    throw error;
  }
};
const show = electron.dialog.showErrorBox;
electron.dialog.showErrorBox = function (title, content) {
  trace.dialogs.push({ at: Date.now(), title, content });
  save();
  return show.call(this, title, content);
};
const load = electron.BrowserWindow.prototype.loadURL;
electron.BrowserWindow.prototype.loadURL = function (url, ...args) {
  trace.loads.push({ at: Date.now(), url });
  save();
  return load.call(this, url, ...args);
};
process.on('uncaughtExceptionMonitor', (error, origin) => {
  trace.monitor.push({ name: error.name, code: error.code, message: error.message, origin });
  save();
});
save();

'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const cp = require('node:child_process');
const { createRequire } = require('node:module');
const { promisify } = require('node:util');
const { setTimeout: delay } = require('node:timers/promises');
const [repo, runtimeRoot, phase, packaged] = process.argv.slice(2);
const load = createRequire(path.join(repo, 'package.json'));
const { _electron } = load('playwright');
const executable = packaged || load('electron');
const run = promisify(cp.execFile);
const output = fs.mkdtempSync(path.join(os.tmpdir(), `pd-r7-sync-${phase}-`));
console.log(`Synchronous failure artifacts: ${output}`);
const home = path.join(output, 'home');
fs.mkdirSync(home);
fs.mkdirSync(path.join(output, 'tmux'));
const inherited = Object.fromEntries(['PATH', 'DISPLAY', 'XAUTHORITY', 'LANG'].filter(key => process.env[key]).map(key => [key, process.env[key]]));
const env = { ...load('./test/test-env').sanitizeTestEnv({ ...inherited, HOME: home }), PORT: '-1', TMUX_TMPDIR: path.join(output, 'tmux'),
  XDG_CONFIG_HOME: path.join(home, '.config'), XDG_CACHE_HOME: path.join(home, '.cache'), R7_TRACE: path.join(output, 'trace.json') };
let child;
let app;
let launchError;
let outputText = '';
let exit = null;
const nativeSpawn = cp.spawn;
cp.spawn = function (...args) {
  const spawned = nativeSpawn.apply(this, args);
  if (args[0] === executable) {
    child = spawned;
    child.once('exit', (code, signal) => { exit = { code, signal }; });
    child.stderr.on('data', data => { outputText += data; });
    child.stdout.on('data', data => { outputText += data; });
  }
  return spawned;
};
const watchdog = setTimeout(() => { if (child?.exitCode === null) child.kill('SIGKILL'); console.error('Synchronous proof watchdog expired'); process.exit(1); }, 25000);
(async () => {
  const launched = require('/tmp/pi-dish-parent-r7-main-YyExzk/pi-dish-r7-electron-launch.cjs')(_electron, {
    executablePath: executable,
    args: ['-r', '/tmp/pi-dish-parent-r7-main-YyExzk/pi-dish-r7-sync-preload.cjs', ...(packaged ? [] : [path.join(runtimeRoot, 'electron/main.js')])],
    cwd: output, env, timeout: 15000,
  }, !!packaged);
  launched.then(value => { app = value; }, error => { launchError = String(error); });
  let trace;
  let dismissed = 0;
  let thrownAt;
  try {
    for (let attempt = 0; attempt < 160; attempt++) {
      if (fs.existsSync(env.R7_TRACE)) trace = JSON.parse(fs.readFileSync(env.R7_TRACE));
      if (trace?.throws.length && !thrownAt) thrownAt = Date.now();
      if ((trace?.dialogs.length || 0) > dismissed) {
        await delay(400);
        await run('import', ['-window', 'root', path.join(output, `dialog${dismissed + 1}.png`)], { env });
        await run('python3', ['/tmp/pi-dish-parent-r7-main-YyExzk/pi-dish-r7-dismiss-dialog.py'], { env });
        dismissed++;
      }
      if (exit || (thrownAt && Date.now() - thrownAt > 2500)) break;
      await delay(50);
    }
    assert.ok(trace?.throws.some(error => error.name === 'RangeError' && error.code === 'ERR_SOCKET_BAD_PORT'));
    assert.deepEqual(trace.loads, []);
    fs.writeFileSync(path.join(output, 'result.json'), JSON.stringify({ phase, runtimeRoot, result: 'OBSERVED', processAlive: child.exitCode === null, exit, dismissed, trace, outputText, launchError }, null, 2));
    console.log(JSON.stringify({ phase, processAlive: child.exitCode === null, exit, dialogs: trace.dialogs.length, nativeMonitor: trace.monitor }, null, 2));
  } finally {
    cp.spawn = nativeSpawn;
    fs.writeFileSync(path.join(output, 'process.log'), outputText);
    if (app && child.exitCode === null) await app.close();
    else if (child?.exitCode === null) {
      child.kill('SIGTERM');
      await new Promise(resolve => child.once('exit', resolve));
    }
    await launched.catch(() => {});
    clearTimeout(watchdog);
  }
})().catch(error => { console.error(error); process.exitCode = 1; clearTimeout(watchdog); });

'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const net = require('node:net');
const { createRequire } = require('node:module');
const { execFile } = require('node:child_process');
const { promisify } = require('node:util');
const { setTimeout: delay } = require('node:timers/promises');
const run = promisify(execFile);
const [repo, mode = 'dev', phase = 'baseline', packaged, timing = 'together'] = process.argv.slice(2);
const load = createRequire(path.join(repo, 'package.json'));
const { _electron } = load('playwright');
const { sanitizeTestEnv } = load('./test/test-env');
const output = fs.mkdtempSync(path.join(os.tmpdir(), `pd-r7-share-${mode}-${phase}-${timing}-`));
console.log(`Share failure artifacts: ${output}`);
const home = path.join(output, 'home');
fs.mkdirSync(home);
fs.mkdirSync(path.join(output, 'tmux'));
const inherited = Object.fromEntries(['PATH', 'DISPLAY', 'XAUTHORITY', 'LANG'].filter(key => process.env[key]).map(key => [key, process.env[key]]));
const env = { ...sanitizeTestEnv({ ...inherited, HOME: home }), TMUX_TMPDIR: path.join(output, 'tmux'),
  XDG_CONFIG_HOME: path.join(home, '.config'), XDG_CACHE_HOME: path.join(home, '.cache'),
  R7_DELAY_MS: '1500', R7_TRACE: path.join(output, 'trace.json') };
if (timing === 'late-main') env.R7_MAIN_DELAY_MS = '5000';
const watchdog = setTimeout(() => { console.error('Share proof watchdog expired'); process.exit(1); }, 35000);
(async () => {
  const occupied = net.createServer(socket => socket.end());
  await new Promise(resolve => occupied.listen(0, '127.0.0.1', resolve));
  env.PI_DISH_SHARE_PORT = String(occupied.address().port);
  let app;
  let child;
  try {
    app = await require('/tmp/pi-dish-parent-r7-main-YyExzk/pi-dish-r7-electron-launch.cjs')(_electron, { executablePath: mode === 'dev' ? load('electron') : packaged,
      args: ['-r', '/tmp/pi-dish-parent-r7-main-YyExzk/pi-dish-r7-electron-preload.cjs', ...(mode === 'dev' ? [path.join(repo, 'electron/main.js')] : [])],
      cwd: output, env, timeout: 15000 }, mode === 'packaged');
    child = app.process();
    const logs = [];
    child.stderr?.on('data', data => { logs.push(String(data)); fs.writeFileSync(path.join(output, 'stderr.log'), logs.join('')); });
    let trace;
    for (let expected = 1; expected <= (phase === 'baseline' ? 1 : 2); expected++) {
      for (let i = 0; i < 200; i++) {
        trace = JSON.parse(fs.readFileSync(env.R7_TRACE));
        if (trace.dialogs.length >= expected) break;
        if (child.exitCode !== null) throw new Error(`Exited before native error dialog: ${child.exitCode}`);
        await delay(50);
      }
      assert.ok(trace.dialogs.length >= expected, `Missing dialog${expected}: ${JSON.stringify(trace)}`);
      assert.match(trace.dialogs[expected - 1].content, /EADDRINUSE|address already in use/);
      await delay(500);
      await run('import', ['-window', 'root', path.join(output, `dialog${expected}.png`)], { env });
      await run('python3', ['/tmp/pi-dish-parent-r7-main-YyExzk/pi-dish-r7-dismiss-dialog.py'], { env });
    }
    await delay(700);
    assert.equal(child.exitCode, null, 'Electron native uncaught-exception handler keeps its process alive');
    let main;
    for (let attempt = 0; attempt < 100; attempt++) {
      trace = JSON.parse(fs.readFileSync(env.R7_TRACE));
      main = trace.binds.find(bind => bind.listening && bind.port === 0);
      if (main) break;
      await delay(50);
    }
    assert.ok(main);
    if (timing === 'late-main') assert.ok(trace.dialogs[0].at < main.listening);
    if (phase === 'final') {
      const window = await app.firstWindow({ timeout: 10000 });
      await window.waitForURL(`http://127.0.0.1:${main.address.port}/`, { waitUntil: 'domcontentloaded' });
      trace = JSON.parse(fs.readFileSync(env.R7_TRACE));
      assert.equal(trace.loads.length, 1);
      assert.ok(trace.loads[0].at >= main.listening);
      await window.screenshot({ path: path.join(output, 'window.png') });
    }
    const response = await fetch(`http://127.0.0.1:${main.address.port}/api/host`, { signal: AbortSignal.timeout(3000) });
    assert.equal(response.status, 200);
    assert.equal(occupied.listening, true);
    fs.writeFileSync(path.join(output, 'result.json'), JSON.stringify({ result: 'PASS', mode, phase, timing, trace, nativeHostOutcome: 'alive with main HTTP200 after uncaught share error' }, null, 2));
    console.log(`${mode}/${phase}: native Electron share failure outcome PASS`);
  } catch (error) {
    console.error(error);
    process.exitCode = 1;
  } finally {
    try { if (app && child?.exitCode === null) await app.close(); }
    finally { await new Promise(resolve => occupied.close(resolve)); clearTimeout(watchdog); }
  }
})().catch(error => { console.error(error); process.exitCode = 1; clearTimeout(watchdog); });
